"""Voice event composer."""

from __future__ import annotations

import asyncio
import time
from contextlib import contextmanager
from contextvars import ContextVar
from typing import (
    Awaitable,
    Callable,
    Dict,
    Generator,
    Optional,
    Sequence,
    Set,
)

import structlog

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.channels.voice_stream.call_state import call_state
from rasa.core.channels.voice_stream.channel_controller.channel_controller import (
    ChannelController,
)
from rasa.core.voice.dtmf import ActiveDTMFCollectResolver
from rasa.core.voice.event_composition.composer.orchestrator import (
    Handler,
    HandlerOrchestrator,
)
from rasa.core.voice.event_composition.events.input_events import (
    FinalTranscriptInputEvent,
    InputEvent,
    SessionEndedInputEvent,
)
from rasa.core.voice.event_composition.handlers import (
    BargeInHandler,
    DTMFHandler,
    LifecycleHandler,
    PendingEventHandler,
    PlaybackTrackingHandler,
    SilenceHandler,
    TranscriptMergeHandler,
)
from rasa.core.voice.event_composition.queues import InteractionEventQueue
from rasa.tracing import voice as voice_tracing

structlogger = structlog.get_logger()

_turn_input_queue: ContextVar[Optional[InteractionEventQueue]] = ContextVar(
    "voice_turn_input_queue", default=None
)


def get_current_turn_input_queue() -> Optional[InteractionEventQueue]:
    """Return the interaction queue available to the current voice turn.

    Returns ``None`` outside an event-composer turn, for example on text
    channels.
    """
    return _turn_input_queue.get()


class EventComposer:
    """Move raw events through composition handlers into an interaction queue."""

    def __init__(
        self,
        *,
        sender_id: str,
        raw_event_queue: ConversationQueue[InputEvent],
        resolve_active_dtmf_collect: ActiveDTMFCollectResolver,
        interaction_event_queue: Optional[InteractionEventQueue] = None,
        channel_controller: Optional[ChannelController] = None,
        on_barge_in_accepted: Optional[Callable[[], Awaitable[None]]] = None,
        on_session_ended: Optional[Callable[[], object]] = None,
    ) -> None:
        """Create an event composer and its handler dependency graph."""
        self.raw_event_queue = raw_event_queue
        self.interaction_event_queue = interaction_event_queue or InteractionEventQueue(
            conversation_id=raw_event_queue.conversation_id,
            input_channel=raw_event_queue.input_channel,
        )

        # Instantiate handlers
        playback_handler = PlaybackTrackingHandler(
            self.interaction_event_queue,
            channel_controller,
        )
        barge_in_handler = BargeInHandler(
            self.interaction_event_queue,
            on_barge_in_accepted,
            on_barge_in_detected=[playback_handler.clear_playback_state],
            barge_in_metadata_provider=playback_handler.get_barge_in_metadata,
            bot_text_provider=playback_handler.get_playing_bot_text,
        )
        dtmf_handler = DTMFHandler(
            sender_id,
            resolve_active_dtmf_collect,
            self.interaction_event_queue,
        )
        silence_handler = SilenceHandler(
            self.interaction_event_queue,
            on_silence_detected=[dtmf_handler.handle_timeout],
        )
        self._silence_handler = silence_handler
        lifecycle_handler = LifecycleHandler(
            self.interaction_event_queue, on_session_ended
        )
        transcript_handler = TranscriptMergeHandler(self.interaction_event_queue)

        # Create a dependency graph of handlers. Keys are handlers, values are sets of
        # handlers that must finish before the key starts.
        handler_dependencies: Dict[Handler, Set[Handler]] = {
            playback_handler: set(),
            barge_in_handler: {playback_handler},
            silence_handler: {playback_handler},
            dtmf_handler: set(),
            lifecycle_handler: {playback_handler},
            transcript_handler: {
                barge_in_handler,
                dtmf_handler,
                lifecycle_handler,
            },
        }
        self._handler_orchestrator = HandlerOrchestrator(handler_dependencies)

        # Pending handlers buffer events while one get_batch() result is processed
        # and emit them after that list has been handled.
        self._pending_handlers = [
            handler
            for handler in self._handler_orchestrator.handlers
            if isinstance(handler, PendingEventHandler)
        ]

        # Events that don't require a pending flush.
        self._events_without_pending_flush = (FinalTranscriptInputEvent,)

    async def compose(self, events: Sequence[InputEvent]) -> None:
        """Compose a raw input batch through immediate and pending handler work.

        Each event completes its dependency graph before continuing. Pending handlers
        are flushed at configured event boundaries and at the end of the batch.
        """
        for event in events:
            # Flush pending handlers unless this event allows continued buffering.
            if not isinstance(event, self._events_without_pending_flush):
                await self._flush_pending_events()

            # Timestamp used only when recording a dispatch failure.
            dispatch_started_ns = time.time_ns()
            try:
                # Complete this event's handler graph before continuing.
                await self._handler_orchestrator.dispatch(event)
            except Exception as error:
                structlogger.exception(
                    "event_composer.event_composition_failed",
                    conversation_id=self.interaction_event_queue.conversation_id,
                    event_type=type(event).__name__,
                    error_type=type(error).__name__,
                )
                voice_tracing.record_event_composition_failure(
                    error,
                    event_type=type(event).__name__,
                    start_time_ns=dispatch_started_ns,
                )
                raise

        await self._flush_pending_events()

    async def process_next_batch(self) -> bool:
        """Read one raw batch, compose it, and enqueue interaction events."""
        raw_events = await self.raw_event_queue.get_batch()
        await self.compose(raw_events)
        return any(isinstance(e, SessionEndedInputEvent) for e in raw_events)

    async def run(self) -> None:
        """Continuously compose raw events until the raw stream ends."""
        while True:
            session_ended = await self.process_next_batch()
            if session_ended:
                return

    @contextmanager
    def turn(self) -> Generator[None, None, None]:
        """Mark the call as processing for the duration of one turn.

        The processor wraps each interaction event it handles in this block. On
        entry, silence monitoring stops, so a watcher armed at the end of the
        previous turn cannot fire while this one runs. On exit, a turn that left
        nothing playing arms the silence watcher; otherwise the playback-stopped
        event does. A turn that raises does not arm it: the call is ending.
        """
        turn_input_queue_token = _turn_input_queue.set(self.interaction_event_queue)
        try:
            call_state.is_rasa_processing = True
            self._silence_handler.disarm()
            yield
        finally:
            call_state.is_rasa_processing = False
            _turn_input_queue.reset(turn_input_queue_token)
        self._silence_handler.arm_if_idle()

    async def _flush_pending_events(self) -> None:
        """Ask buffering handlers to emit events pending at the batch boundary."""
        await asyncio.gather(
            *(handler.flush_pending_events() for handler in self._pending_handlers)
        )
